    static String testReason(String reason){switch(reason){case "timeout":return "20秒测试结束";case "user_stop":return "手动停止";case "manual":case "manual_mode":return "手动亮度接管";case "screen_off":return "已锁屏或熄屏";case "hdr":case "protected_frame":return "特殊画面接管";case "temperature":return "温度条件变化";case "power_save":return "省电限制";case "display_changed":case "user_changed":return "屏幕或用户已切换";case "configuration_changed":return "设置已更改";case "engine_closed":case "inactive":return "亮度引擎已退出";case "owned_or_locked":case "node_mode":return "其他亮度控制接管";case "native_error":case "start_failed":case "install_failed":return "原生接口未完成测试";default:return "系统条件变化";}}
    void leave(){org.json.JSONObject state=testState();String session=state!=null&&state.optBoolean("active")?state.optString("session"):testSession;if(stoppingTest||session.isEmpty())return;stoppingTest=true;a.stopOutdoorTestQuietly(testPayload("stop",session));}
